<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-0">Dashboard</h1><div class="text-muted">Realbau-Planung für Leitstellenspiel.de</div></div><a class="btn btn-danger" href="/projects">Projekt anlegen</a></div><div class="row g-3 mb-4"><?php foreach($stats as $label=>$value): ?><div class="col-6 col-md"><div class="card stat-card"><div class="card-body"><div class="text-muted small text-uppercase"><?=e(str_replace('_',' ', $label))?></div><div class="display-6 fw-bold"><?=e($value)?></div></div></div></div><?php endforeach; ?></div><div class="card"><div class="card-header fw-bold">Projekte</div><div class="card-body"><?php if(!$projects): ?><p class="text-muted mb-0">Noch keine Projekte vorhanden.</p><?php else: ?><div class="row g-3"><?php foreach($projects as $p): ?><div class="col-md-4"><div class="border rounded p-3 h-100"><h2 class="h5"><?=e($p['name'])?></h2><div class="text-muted small mb-2"><?=e($p['station_count'])?> geplante Wachen</div><p><?=e($p['description'])?></p></div></div><?php endforeach; ?></div><?php endif; ?></div></div>